 it('各死亡事件可設定不同窗口；未設定窗口不繼承 30 日並於觸發日落實',()=>{const samples:HistoricalNodeContent[]=[{id:'test-death-five',kind:'death',title:'五日窗口人物',startYear:185,endYear:185,precision:'year',source:'測試用工程情境。',causes:[],carrier:'五日窗口人物',historicalPersonId:'test-five',description:'測試專用。'},{id:'test-death-two',kind:'death',title:'二日窗口人物',startYear:185,endYear:185,precision:'year',source:'測試用工程情境。',causes:[],carrier:'二日窗口人物',historicalPersonId:'test-two',description:'測試專用。'},{id:'test-death-none',kind:'death',title:'未設窗口人物',startYear:185,endYear:185,precision:'year',source:'測試用工程情境。',causes:[],carrier:'未設窗口人物',historicalPersonId:'test-none',description:'測試專用。'}];HISTORY_CONTENT.push(...samples);ENGINEERING.deathInterventionWindowDaysByEvent['test-death-five']=5;ENGINEERING.deathInterventionWindowDaysByEvent['test-death-two']=2;try{let m=model();m.historicalPersons.push(...[{id:'test-five',name:'五日窗口人物',alive:true,location:'示例地點',role:'測試人物',source:'測試'},{id:'test-two',name:'二日窗口人物',alive:true,location:'示例地點',role:'測試人物',source:'測試'},{id:'test-none',name:'未設窗口人物',alive:true,location:'示例地點',role:'測試人物',source:'測試'}]);m=advancePhase4(m,360);const status=(id:string)=>m.nodes.find(n=>n.contentId===id)?.status;expect(status('test-death-five')).toBe('triggered');expect(status('test-death-two')).toBe('triggered');expect(status('test-death-none')).toBe('resolved');expect(m.historicalPersons.find(p=>p.id==='test-none')?.alive).toBe(false);expect(()=>act(m,{type:'InterveneDeath',nodeId:'test-death-none',personId:'test-none',method:'一般醫療',location:'示例地點'})).toThrow('沒有仍在個別死亡介入窗口內的存活人物');expect(m.historicalPersons.find(p=>p.id==='test-five')?.alive).toBe(true);m=advancePhase4(m,2);expect(m.nodes.find(n=>n.contentId==='test-death-two')?.status).toBe('resolved');expect(m.historicalPersons.find(p=>p.id==='test-two')?.alive).toBe(false);expect(m.nodes.find(n=>n.contentId==='test-death-five')?.status).toBe('triggered');expect(m.historicalPersons.find(p=>p.id==='test-five')?.alive).toBe(true);m=advancePhase4(m,3);expect(m.nodes.find(n=>n.contentId==='test-death-five')?.status).toBe('resolved');expect(m.historicalPersons.find(p=>p.id==='test-five')?.alive).toBe(false);}finally{for(const sample of samples){const index=HISTORY_CONTENT.findIndex(item=>item.id===sample.id);if(index>=0)HISTORY_CONTENT.splice(index,1);delete ENGINEERING.deathInterventionWindowDaysByEvent[sample.id];}}});
